import{_ as o,C as n,o as r,c as i,j as t,a as s,E as l,a6 as d}from"./chunks/framework.CA8SQds3.js";const h="/screenshots/picker-lint.png",v=JSON.parse(`{"title":"Lint overlay","description":"Piwi Picker's lint overlay: the interactive elements of a page no stable locator finds alone, each with the test id or the scope to add.","frontmatter":{"title":"Lint overlay","description":"Piwi Picker's lint overlay: the interactive elements of a page no stable locator finds alone, each with the test id or the scope to add.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/lint-overlay.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/lint-overlay.html"}],["meta",{"property":"og:title","content":"Lint overlay | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Piwi Picker's lint overlay: the interactive elements of a page no stable locator finds alone, each with the test id or the scope to add."}]]},"headers":[],"relativePath":"features/lint-overlay.md","filePath":"features/lint-overlay.md","lastUpdated":1792792684000}`),c={name:"features/lint-overlay.md"};function p(m,e,u,f,g,y){const a=n("Needs");return r(),i("div",null,[e[0]||(e[0]=t("h1",{id:"lint-overlay",tabindex:"-1"},[s("Lint overlay "),t("a",{class:"header-anchor",href:"#lint-overlay","aria-label":'Permalink to "Lint overlay"'},"​")],-1)),l(a,{extension:""}),e[1]||(e[1]=d('<p>The <strong>Lint overlay</strong>, under <strong>More tools</strong> in the <a href="./extension.html">Piwi Picker</a> popup, checks every button, link and field of the page with the ranking <a href="./pick-an-element.html">Pick an element</a> uses.</p><p>One click outlines every interactive element no stable locator finds alone and says what to add, with a <strong>Copy</strong> button for each and <strong>Copy as a Markdown checklist</strong> for all of them:</p><ul><li><strong>A test id named after the element</strong>: its accessible name, label or placeholder, else the nearest heading with the role (<code>data-testid=&quot;submit-order&quot;</code> for a button named &quot;Submit order&quot;, <code>shipping-address-button</code>), else the role. A value the page already uses, or another suggestion took, gets <code>-2</code>, <code>-3</code>.</li><li><strong>A test id on the repeated container</strong> when the element sits in a row, a card or a list item whose copies hold the same element: named after the text that tells this copy apart (<code>data-testid=&quot;blue-mug&quot;</code>), with the locator a test then uses, <code>getByTestId(&#39;blue-mug&#39;).getByRole(&#39;button&#39;, { name: &#39;Add to cart&#39; })</code>. The container and the text are the ones <a href="./pick-an-element.html">Pick an element</a> narrows by: the nearest container whose copies hold the other elements, and a text no other copy contains, a heading first, then a name rather than a price or a count, a visible text before a hidden one. The container is outlined in amber.</li><li><strong>A scope</strong> when those copies already share a test id: no attribute to add, the locator filters by the copy&#39;s text, <code>getByTestId(&#39;product-card&#39;).filter({ hasText: &#39;Blue mug&#39; }).getByRole(&#39;button&#39;, { name: &#39;Add to cart&#39; })</code>.</li></ul><figure><img src="'+h+'" alt="Four unnamed wishlist icon buttons outlined in their product cards, each with a test id named after its card&#39;s heading"><figcaption>Lint overlay: four icon buttons without a name; each gets a test id named after its card&#39;s heading. The Add to cart buttons beside them are not listed: the ranking finds each one through its card.</figcaption></figure><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./pick-an-element.html">Pick an element</a>: the ranked locators of one element</li><li><a href="/reference/locator-stability.html">Locator stability</a>: what makes a locator stable</li><li><a href="./extension.html">Browser extension</a>: the other tools and the permissions</li></ul>',6))])}const w=o(c,[["render",p]]);export{v as __pageData,w as default};
